mapper.select:
SELECT t.*, u.name, u.username FROM base_rbac_user_role t LEFT JOIN base_user u ON t.user_id = u.id WHERE t.deleted = 0 AND u.deleted = 0
AND t.role_id = #{query.roleId}
AND u.name LIKE concat('%', #{query.name}, '%')
AND u.username LIKE concat('%', #{query.username}, '%')
ORDER BY ${sorter}

SELECT t.*, u.name, u.username FROM base_rbac_user_role t LEFT JOIN base_user u ON t.user_id = u.id WHERE t.deleted = false AND u.deleted = false
AND t.role_id = #{query.roleId}
AND u.name LIKE concat('%', #{query.name}, '%')
AND u.username LIKE concat('%', #{query.username}, '%')
ORDER BY ${sorter}

SELECT count(0) FROM base_rbac_menu m WHERE deleted = 0 AND status = 1 AND id IN ( SELECT rm.menu_id FROM base_rbac_role_menu rm JOIN base_rbac_user_role ur ON ur.role_id = rm.role_id JOIN base_rbac_role r ON r.id = ur.role_id WHERE rm.deleted = 0 AND ur.deleted = 0 AND r.deleted = 0 AND r.status = 1 AND ur.user_id = #{userId}
AND ((r.type = 2 AND (r.tenant_id IS NULL OR r.tenant_id = '')) OR (r.type = 3 AND r.tenant_id = #{tenantId}))
) AND link_url = #{linkUrl}
AND (m.tenant_required = TRUE OR EXISTS ( SELECT 1 FROM tn_tenant_permission tp WHERE tp.tenant_id = #{tenantId} AND tp.menu_id = m.id AND tp.deleted = 0 ))

SELECT count(0) FROM base_rbac_menu m WHERE m.deleted = false AND m.status = true AND m.id IN ( SELECT rm.menu_id FROM base_rbac_role_menu rm JOIN base_rbac_user_role ur ON ur.role_id = rm.role_id JOIN base_rbac_role r ON r.id = ur.role_id WHERE rm.deleted = false AND ur.deleted = false AND r.deleted = false AND r.status = true AND ur.user_id = #{userId}
AND ((r.type = 2 AND (r.tenant_id IS NULL OR r.tenant_id = '')) OR (r.type = 3 AND r.tenant_id = #{tenantId}))
) AND m.link_url = #{linkUrl}
AND (m.tenant_required = TRUE OR EXISTS ( SELECT 1 FROM tn_tenant_permission tp WHERE tp.tenant_id = #{tenantId} AND tp.menu_id = m.id AND tp.deleted = false ))
